"""Generate the dbt `sources` YAML from the schema contracts (single source of truth).

The generated file is committed, and a test fails if it drifts from the contracts, so
column descriptions and classifications are written once and reused everywhere.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

import yaml

from zap.ingest.contracts import Contract

HEADER = (
    "# GENERATED by `zap gen-dbt-sources` from contracts/*.yml. Do not edit by hand:\n"
    "# change the contract and regenerate.\n"
)
FRESHNESS = {
    "warn_after": {"count": 26, "period": "hour"},
    "error_after": {"count": 50, "period": "hour"},
}


def _table(contract: Contract) -> dict[str, Any]:
    columns = [
        {
            "name": c.name,
            "description": c.description,
            "data_type": c.type,
            "meta": {"classification": c.classification},
        }
        for c in contract.columns
    ]
    columns += [
        {"name": "_batch_id", "description": "Ingestion run that wrote the row."},
        {"name": "_source_file", "description": "Source CSV file name."},
        {"name": "_loaded_at", "description": "UTC time the row was ingested."},
    ]
    if contract.partition_lookup and contract.partition_by:
        columns.append(
            {
                "name": contract.partition_by,
                "description": f"Partition date looked up from {contract.partition_lookup.table}.",
            }
        )
    table: dict[str, Any] = {
        "name": contract.table,
        "description": " ".join(contract.description.split()),
        "meta": {"file": contract.file, "kind": contract.kind, "primary_key": contract.primary_key},
        "columns": columns,
    }
    if contract.kind == "fact":
        # Freshness uses ingestion time: business dates in this static dataset end in 2026-06.
        table["config"] = {"loaded_at_field": "_loaded_at", "freshness": FRESHNESS}
    return table


def render_sources(contracts: dict[str, Contract]) -> str:
    doc = {
        "version": 2,
        "sources": [
            {
                "name": "raw",
                "schema": "raw",
                "description": "Source files as delivered, loaded from the lake.",
                "tables": [_table(c) for c in contracts.values()],
            }
        ],
    }
    return HEADER + yaml.safe_dump(doc, sort_keys=False, allow_unicode=True, width=100)


def write_sources(contracts: dict[str, Contract], path: Path) -> bool:
    """Write the sources file; return True if its content changed."""
    text = render_sources(contracts)
    if path.exists() and path.read_text(encoding="utf-8") == text:
        return False
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")
    return True
